// src/context/AuthContext.js
import React, { createContext, useContext, useEffect, useState, useCallback } from 'react';
import {
  getAuth,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  signInWithPopup,
  GoogleAuthProvider,
  signOut,
  updateProfile,
  deleteUser,
  reauthenticateWithCredential,
  EmailAuthProvider,
} from 'firebase/auth';
import {
  getFirestore,
  doc,
  setDoc,
  getDoc,
  updateDoc,
  deleteDoc,
} from 'firebase/firestore';
import {
  getStorage,
  ref as storageRef,
  uploadBytes,
  getDownloadURL,
  deleteObject,
} from 'firebase/storage';
import { initializeApp } from 'firebase/app';

const firebaseConfig = {
  apiKey:            process.env.REACT_APP_FIREBASE_API_KEY,
  authDomain:        process.env.REACT_APP_FIREBASE_AUTH_DOMAIN,
  projectId:         process.env.REACT_APP_FIREBASE_PROJECT_ID,
  storageBucket:     process.env.REACT_APP_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID,
  appId:             process.env.REACT_APP_FIREBASE_APP_ID,
};

const app     = initializeApp(firebaseConfig);
const auth    = getAuth(app);
const db      = getFirestore(app);
const storage = getStorage(app);

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
  const [user,    setUser]    = useState(null);
  const [profile, setProfile] = useState(null);
  const [loading, setLoading] = useState(true);

  // Listen to Firebase auth state
  useEffect(() => {
    const unsub = auth.onAuthStateChanged(async (firebaseUser) => {
      setUser(firebaseUser);
      if (firebaseUser) {
        const token = await firebaseUser.getIdToken();
        localStorage.setItem('token', token);
        const snap = await getDoc(doc(db, 'users', firebaseUser.uid));
        if (snap.exists()) {
          setProfile(snap.data());
        } else {
          setProfile(null);
        }
      } else {
        localStorage.removeItem('token');
        setProfile(null);
      }
      setLoading(false);
    });
    return unsub;
  }, []);

  // Memoized getToken to avoid re-renders in dependent components
  const getToken = useCallback(async () => {
    if (!auth.currentUser) return null;
    return auth.currentUser.getIdToken(true);
  }, []);

  // Sign up with email
  const signup = async (email, password, displayName) => {
    const cred = await createUserWithEmailAndPassword(auth, email, password);
    await updateProfile(cred.user, { displayName });
    const userData = {
      displayName,
      email,
      organization:     '',
      country:          '',
      bio:              '',
      photoURL:         '',
      totalPredictions: 0,
      createdAt:        new Date().toISOString(),
    };
    await setDoc(doc(db, 'users', cred.user.uid), userData);
    setProfile(userData);
    return cred;
  };

  // Sign in with email
  const login = (email, password) =>
    signInWithEmailAndPassword(auth, email, password);

  // Google sign-in — FIX: renamed local variable to avoid shadowing storageRef import
  const loginWithGoogle = async () => {
    const provider = new GoogleAuthProvider();
    const cred = await signInWithPopup(auth, provider);

    const userDocRef = doc(db, 'users', cred.user.uid);
    const snap = await getDoc(userDocRef);

    if (!snap.exists()) {
      const userData = {
        displayName:      cred.user.displayName || '',
        email:            cred.user.email,
        organization:     '',
        country:          '',
        bio:              '',
        photoURL:         cred.user.photoURL || '',
        totalPredictions: 0,
        createdAt:        new Date().toISOString(),
      };
      await setDoc(userDocRef, userData);
      setProfile(userData);
    } else {
      setProfile(snap.data());
    }
    return cred;
  };

  // Logout
  const logout = async () => {
    await signOut(auth);
    localStorage.removeItem('token');
    setProfile(null);
  };

  // Update profile fields — FIX: returns updated profile so callers can rely on it
  const updateUserProfile = async (fields) => {
    if (!auth.currentUser) return;
    await updateDoc(doc(db, 'users', auth.currentUser.uid), fields);
    if (fields.displayName) {
      await updateProfile(auth.currentUser, { displayName: fields.displayName });
    }
    if (fields.photoURL !== undefined) {
      await updateProfile(auth.currentUser, { photoURL: fields.photoURL });
    }
    setProfile(prev => ({ ...prev, ...fields }));
  };

  // Increment prediction count (call this after each successful prediction)
  const incrementPredictions = async () => {
    if (!auth.currentUser) return;
    const newCount = (profile?.totalPredictions || 0) + 1;
    await updateDoc(doc(db, 'users', auth.currentUser.uid), {
      totalPredictions: newCount,
    });
    setProfile(prev => ({ ...prev, totalPredictions: newCount }));
  };

  // Upload profile picture
  const uploadProfilePicture = async (file) => {
    if (!auth.currentUser) return;
    const avatarRef = storageRef(storage, `avatars/${auth.currentUser.uid}`);
    await uploadBytes(avatarRef, file);
    const url = await getDownloadURL(avatarRef);
    await updateProfile(auth.currentUser, { photoURL: url });
    await updateDoc(doc(db, 'users', auth.currentUser.uid), { photoURL: url });
    setProfile(prev => ({ ...prev, photoURL: url }));
  };

  // Remove profile picture
  const removeProfilePicture = async () => {
    if (!auth.currentUser) return;
    try {
      await deleteObject(storageRef(storage, `avatars/${auth.currentUser.uid}`));
    } catch (_) { /* ignore if no file */ }
    await updateProfile(auth.currentUser, { photoURL: '' });
    await updateDoc(doc(db, 'users', auth.currentUser.uid), { photoURL: '' });
    setProfile(prev => ({ ...prev, photoURL: '' }));
  };

  // Delete account
  const deleteAccount = async (password) => {
    if (!auth.currentUser) return;
    const credential = EmailAuthProvider.credential(auth.currentUser.email, password);
    await reauthenticateWithCredential(auth.currentUser, credential);
    await deleteDoc(doc(db, 'users', auth.currentUser.uid));
    await deleteUser(auth.currentUser);
    localStorage.removeItem('token');
  };

  // Refresh profile from Firestore (useful for dashboard/history to force sync)
  const refreshProfile = async () => {
    if (!auth.currentUser) return;
    const snap = await getDoc(doc(db, 'users', auth.currentUser.uid));
    if (snap.exists()) {
      setProfile(snap.data());
    }
  };

  const value = {
    user,
    profile,
    loading,
    getToken,
    signup,
    login,
    loginWithGoogle,
    logout,
    updateUserProfile,
    uploadProfilePicture,
    removeProfilePicture,
    deleteAccount,
    incrementPredictions,
    refreshProfile,
  };

  if (loading) return null;

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);
